-- 7) Verification queries
SELECT 'WAs' AS what, count(*)::text AS val FROM resource.work_activities
UNION ALL SELECT 'norms (role-scoped)', count(*)::text FROM resource.productivity_norms WHERE role_id IS NOT NULL
UNION ALL SELECT 'norms (unscoped)',    count(*)::text FROM resource.productivity_norms WHERE role_id IS NULL
UNION ALL SELECT 'OMAN act w/o WA',  count(*)::text FROM activity.activities WHERE project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5' AND work_activity_id IS NULL
UNION ALL SELECT 'OMAN act w/o sup', count(*)::text FROM (SELECT a.id FROM activity.activities a LEFT JOIN activity.activity_supervisors s ON s.activity_id=a.id WHERE a.project_id='d901671a-cd23-41c6-8886-d2c1b0ddd3c5' GROUP BY a.id HAVING count(s.id)=0) z
ORDER BY what;

RESET session_replication_role;
COMMIT;